#define CHECK(x) do {if(!(x)){fprintf(stderr,"C inherited target line %d: %s\n",__LINE__,#x);return 1;}} while(0)
static const char query[]="{\"schema_version\":1,\"required_capabilities\":[\"inherited_fields\",\"use_target_symbol\",\"inherited_target_symbol\"],\"relation\":{\"op\":\"join\",\"on\":\"target_symbol\",\"left\":{\"op\":\"scan\",\"relation\":\"invoke_sites\"},\"right\":{\"op\":\"scan\",\"relation\":\"method_defs\",\"where\":{\"all\":[{\"name\":\"uses\"},{\"declares_fields\":{\"scope\":\"inherited\",\"where\":{\"name\":\"unseen\"},\"min\":0,\"max\":0}}]}}},\"max_results\":100}";
static unsigned char* load(const char* n,long* size){FILE*f=fopen(n,"rb");unsigned char*b;if(!f||fseek(f,0,SEEK_END))return NULL;*size=ftell(f);if(*size<=0){fclose(f);return NULL;}rewind(f);b=(unsigned char*)malloc((size_t)*size);if(!b){fclose(f);return NULL;}if(fread(b,1,(size_t)*size,f)!=(size_t)*size){free(b);fclose(f);return NULL;}fclose(f);return b;}
static int check_result(const dmg_result* r,int batch,int* seen){dmg_relation_info_v2 info;uint32_t i,n,j;CHECK(dmg_result_get_relation_info_v2(r,&info,sizeof(info))==DMG_OK);CHECK(info.execution_status==DMG_OK&&info.relation==DMG_INVOKE_SITES&&info.candidates_count==(batch?1u:8u));
 for(i=0;i<info.candidates_count;++i){dmg_relation_link_v2 link;dmg_value_row_v2 value;uint32_t paths=0;CHECK(dmg_result_get_link_count(r,i,&n)==DMG_OK&&n==1);CHECK(dmg_result_get_link_v2(r,i,0,&link,sizeof(link))==DMG_OK&&link.key==DMG_JOIN_TARGET_SYMBOL);CHECK(link.left.relation==DMG_INVOKE_SITES&&link.left.source_index<2&&link.left.local_index==2&&(link.left.dex_pc==0||link.left.dex_pc==3));CHECK(link.right.relation==DMG_METHOD_DEFS&&link.right.source_index<2&&link.right.local_index==2);CHECK(dmg_result_get_value_v2(r,i,&value,sizeof(value))==DMG_OK&&value.kind==DMG_VALUE_USE&&value.use.target_domain==DMG_TARGET_METHOD_REF&&value.use.target_index==3);
  CHECK(dmg_result_get_witness_count(r,i,&n)==DMG_OK);for(j=0;j<n;++j){dmg_inherited_witness w;unsigned char sentinel[sizeof(w)];dmg_status s;memset(&w,0xa5,sizeof(w));memset(sentinel,0xa5,sizeof(sentinel));CHECK(dmg_result_get_inherited_witness(r,i,j,&w,sizeof(w)-1)==DMG_INVALID_ARGUMENT&&memcmp(&w,sentinel,sizeof(w))==0);s=dmg_result_get_inherited_witness(r,i,j,&w,sizeof(w));if(s==DMG_UNSUPPORTED)continue;CHECK(s==DMG_OK&&w.matched==DMG_MATCH_TRUE);if(w.item_kind==1){if(w.path_index==0)CHECK(w.source_index==link.right.source_index);else if(w.path_index==1)CHECK(w.source_index==2);else CHECK(0);++paths;}}
  CHECK(paths==2);{unsigned ix=(unsigned)link.left.source_index*4u+(unsigned)(link.left.dex_pc/3)*2u+(unsigned)link.right.source_index;CHECK(++seen[ix]==1);}}
 return 0;}
int main(int argc,char**argv){dmg_engine* e=NULL;dmg_snapshot* s=NULL;dmg_query* q=NULL;dmg_result* r=NULL;dmg_job* job=NULL;dmg_batch *b=NULL,*saved=NULL;dmg_error error={0};dmg_source_spec sources[3];dmg_source_set_options so={sizeof(so),DMG_ABI_VERSION,"inherited-target-c",1,3,DMG_MAX_SOURCE_BYTES};dmg_job_options jo={sizeof(jo),DMG_ABI_VERSION,1,1,0};dmg_relation_job_status_v2 status;dmg_query_info qi;unsigned char* bytes[2];long sizes[2];int seen[8]={0};uint32_t i,count=0;
 CHECK(argc==3);bytes[0]=load(argv[1],&sizes[0]);bytes[1]=load(argv[2],&sizes[1]);CHECK(bytes[0]&&bytes[1]);CHECK(dmg_engine_create(NULL,&e,&error)==DMG_OK);for(i=0;i<3;++i){unsigned k=i==2?1:0;sources[i]=(dmg_source_spec){sizeof(dmg_source_spec),DMG_ABI_VERSION,DMG_INPUT_RAW_DEX,0,bytes[k],(uint64_t)sizes[k],i==0?"a":i==1?"a-copy":"parent","code",NULL};}
 CHECK(dmg_snapshot_open_sources(e,sources,3,&so,&s,&error)==DMG_OK);free(bytes[0]);free(bytes[1]);CHECK(dmg_query_compile_json(e,(const uint8_t*)query,strlen(query),&q,&error)==DMG_OK);CHECK(dmg_query_get_info(q,&qi)==DMG_OK&&(qi.required_capabilities&67108864u)&&strncmp(qi.query_id,"query:v18:",10)==0);CHECK(dmg_query_execute(s,q,&r,&error)==DMG_OK&&r);CHECK(check_result(r,0,seen)==0);for(i=0;i<8;++i)CHECK(seen[i]==1);
 CHECK(dmg_job_start(s,q,&jo,&job,&error)==DMG_OK);memset(seen,0,sizeof(seen));while(1){dmg_status next=dmg_job_next(job,5000,&b,&error);if(next==DMG_END_OF_STREAM)break;CHECK(next==DMG_OK&&b);CHECK(check_result(b,1,seen)==0);++count;if(!saved)saved=b;else dmg_batch_release(b);b=NULL;}CHECK(count==8);CHECK(dmg_job_wait_relation_v2(job,5000,&status,sizeof(status))==DMG_OK&&status.terminal&&status.lifecycle==DMG_JOB_COMPLETED&&status.outcome.execution_status==DMG_OK);dmg_job_release(job);dmg_query_release(q);dmg_snapshot_release(s);dmg_engine_release(e);
 {int one[8]={0};CHECK(check_result(saved,1,one)==0);}memset(seen,0,sizeof(seen));CHECK(check_result(r,0,seen)==0);dmg_batch_release(saved);dmg_result_release(r);puts("inherited target C result/Job lifetime passed");return 0;}
